<?php
require_once __DIR__ . '/layout.php';
$id=(int)($_GET['id']??0);$row=leave_get_application($id);if(!$row)die('ไม่พบข้อมูลใบลา');if(!leave_can_edit_application($row)){http_response_code(403);die('403 Forbidden: ไม่สามารถแก้ไขใบลานี้ได้');}
$owner=leave_user_profile_by_id((int)$row['user_id']);if(!$owner)die('ไม่พบข้อมูลผู้ยื่นใบลา');$department=leave_user_department_info($owner);$supervisor=leave_supervisor_for_user($owner);
$types=array();$res=$conn->query("SELECT * FROM leave_types_master WHERE is_active=1 ORDER BY sort_order,id");while($res&&$r=$res->fetch_assoc())$types[]=$r;
$coworkers=array();$ownerId=(int)$row['user_id'];$dept=trim((string)$department['name']);
if($dept!==''){$stmt=$conn->prepare("SELECT id,fullname,department FROM users WHERE status='active' AND id<>? ORDER BY (department=? ) DESC, fullname");$stmt->bind_param('is',$ownerId,$dept);}else{$stmt=$conn->prepare("SELECT id,fullname,department FROM users WHERE status='active' AND id<>? ORDER BY fullname");$stmt->bind_param('i',$ownerId);} $stmt->execute();$res=$stmt->get_result();while($r=$res->fetch_assoc())$coworkers[]=$r;$stmt->close();
leave_page_start('แก้ไขข้อมูลการลา','การแก้ไขข้อมูลจะรีเซ็ตขั้นตอนรับมอบงานและการเห็นชอบ เพื่อให้ตรวจสอบข้อมูลล่าสุดอีกครั้ง','');
?>
