<div class="leave-field leave-col-3"><label>ลาถึงวันที่ <span class="req">*</span></label><input class="leave-input" data-leave-end type="date" name="end_date" value="<?=leave_e($row['end_date'])?>" required></div>
<div class="leave-field leave-col-2"><label>จำนวนวันลา</label><input class="leave-input" data-leave-days type="number" min="0.5" step="0.5" name="leave_days" value="<?=leave_e($row['leave_days'])?>" required></div>
<div class="leave-field leave-col-8"><label>เหตุผลการลา <span class="req">*</span></label><textarea class="leave-textarea" name="reason" required><?=leave_e($row['reason'])?></textarea></div><div class="leave-field leave-col-4"><label>เบอร์ติดต่อ</label><input class="leave-input" name="contact_phone" value="<?=leave_e($row['contact_phone'])?>"></div>
</div></div>
<div class="leave-form-section"><div class="leave-form-section__title"><span class="leave-step">02</span><div><h3>ผู้รับมอบงานและหัวหน้างาน</h3><p>หลังบันทึก ผู้รับมอบงานต้องยืนยันใหม่</p></div></div><div class="leave-form-grid"><div class="leave-field leave-col-6"><label>ผู้รับมอบงาน <span class="req">*</span></label><select class="leave-select" name="handover_user_id" required><?php foreach($coworkers as $c):?><option value="<?=$c['id']?>" <?=(int)$row['handover_user_id']===(int)$c['id']?'selected':''?>><?=leave_e($c['fullname'])?><?=trim((string)$c['department'])!==''?' · '.leave_e($c['department']):''?></option><?php endforeach;?></select></div><div class="leave-field leave-col-6"><label>หัวหน้างาน</label><input class="leave-input" value="<?=leave_e($supervisor?$supervisor['fullname']:'ยังไม่ได้กำหนด')?>" readonly><?php if($supervisor):?><input type="hidden" name="supervisor_user_id" value="<?=$supervisor['id']?>"><?php endif;?><div class="leave-help"><?php if(!$department['has_department']):?>ไม่พบแผนกของผู้ยื่นใบลา<?php elseif(!$supervisor):?>แผนก “<?=leave_e($department['name'])?>” ยังไม่มีหัวหน้างาน<?php else:?>ตรวจแผนก “<?=leave_e($department['name'])?>” และเลือกหัวหน้าแผนกอัตโนมัติ<?php endif;?></div></div></div></div>
