<div class="leave-form-actions"><a class="leave-btn leave-btn--outline" href="detail.php?id=<?=$id?>">ยกเลิก</a><button class="leave-btn leave-btn--primary" <?=$supervisor?'':'disabled'?>>บันทึกการแก้ไข</button></div></form></section>
